		return [
			{
				cadence: 'half',
				degrees: [0, 1, 3, 4],
				id: 'fallback-half',
				modes: ['major', 'minor'],
				weight: 1
			},
			{
				cadence: 'authentic',
				degrees: [0, 3, 4, 0],
				id: 'fallback-authentic',
				modes: ['major', 'minor'],
				weight: 1
			}
		];
