// Alternancia de tema visual y persistencia de preferencia local.
(function (global) {
	'use strict';

	function initialize(options) {
		var preferences = options.preferences;
		var i18n = options.i18n;
		var doc = global.document;
		var button = doc ? doc.getElementById('themeToggleButton') : null;
		var theme = normalizeTheme(options.initialTheme);

		applyTheme(theme);

		if (!button) {
			return;
		}

		updateButton(i18n, theme);

		button.addEventListener('click', function () {
			theme = theme === 'day' ? 'night' : 'day';
			applyTheme(theme);
			updateButton(i18n, theme);

			if (preferences && typeof preferences.setValue === 'function') {
				preferences.setValue('theme', theme);
			}
		});
	}

	function applyTheme(theme) {
		if (global.document && global.document.body) {
			global.document.body.setAttribute('data-theme', normalizeTheme(theme));
		}
	}

	function updateButton(i18n, theme) {
		var doc = global.document;
		var button = doc ? doc.getElementById('themeToggleButton') : null;
		var icon;
		var labelKey = theme === 'day' ? 'theme.switchToNight' : 'theme.switchToDay';

		if (!button) {
			return;
		}

		icon = button.querySelector('.material-icons');

		if (icon) {
			icon.textContent = theme === 'day' ? 'dark_mode' : 'light_mode';
		}

		button.setAttribute('title', translate(i18n, labelKey));
		button.setAttribute('aria-label', translate(i18n, labelKey));
		button.setAttribute('aria-pressed', theme === 'day' ? 'true' : 'false');
	}

	function normalizeTheme(theme) {
		return theme === 'day' ? 'day' : 'night';
	}

	function translate(i18n, key) {
		return i18n && typeof i18n.t === 'function' ? i18n.t(key) : key;
	}

	global.CodaThemeControl = {
		applyTheme: applyTheme,
		initialize: initialize,
		normalizeTheme: normalizeTheme,
		updateButton: updateButton
	};
})(window);

;

/* Source: js/ui/random-select-controller.js */
// Patron reutilizable para botones de azar asociados a controles de formulario.
(function (global) {
	'use strict';

	function initialize(options) {
		var root = options.root || global.document;
		var selector = options.selector || '.randomSelectButton';
		var masterSelector = options.masterSelector || '.randomMasterButton';
		var random = options.random || Math.random;

		if (!root || typeof root.addEventListener !== 'function') {
			return;
		}

		updateLabels(options.i18n, selector);
		updateLabels(options.i18n, masterSelector);

		root.addEventListener('click', function (event) {
			var button = findDelegatedButton(root, event.target, selector);

			if (button) {
				randomizeAssociatedControl(button, random);
			}
		});

		root.addEventListener('click', function (event) {
			var button = findDelegatedButton(root, event.target, masterSelector);

			if (!button) {
				return;
			}

			randomizeAllAssociatedControls(root, random, {
				groups: button.getAttribute('data-random-master-groups'),
				selector: selector
			});
		});
	}

	function updateLabels(i18n, selector) {
		selector = selector || '.randomSelectButton, .randomMasterButton';

		forEachElement(global.document, selector, function (button) {
			var key = button.getAttribute('data-random-i18n-key') || 'randomSelect.label';
			var label = translate(i18n, key);

			button.setAttribute('title', label);
			button.setAttribute('aria-label', label);
		});
	}

	function randomizeAssociatedControl(button, random) {
		var buttonElement = asElement(button);
		var targetSelector = buttonElement ? buttonElement.getAttribute('data-random-control-target') || buttonElement.getAttribute('data-random-select-target') : null;
		var target;

		if (!targetSelector) {
			return null;
		}

		target = global.document ? global.document.querySelector(targetSelector) : null;

		return randomizeControl(target, random);
	}

	function randomizeAssociatedSelect(button, random) {
		return randomizeAssociatedControl(button, random);
	}

	function randomizeAllAssociatedControls(root, random, options) {
		var settings = options || {};
		var selector = settings.selector || '.randomSelectButton';
		var masterGroups = parseGroups(settings.groups);
		var randomizedTargets = {};
		var randomizedValues = [];

		forEachElement(root, selector, function (button) {
			var targetSelector = button.getAttribute('data-random-control-target') || button.getAttribute('data-random-select-target');
			var value;

			if (!targetSelector || randomizedTargets[targetSelector] || !isButtonInMasterGroups(button, masterGroups)) {
				return;
			}

			value = randomizeAssociatedControl(button, random);

			if (value !== null) {
				randomizedTargets[targetSelector] = true;
				randomizedValues.push({
					target: targetSelector,
					value: value
				});
			}
		});

		return randomizedValues;
	}

	function randomizeControl(control, random) {
		var element = asElement(control);

		if (!element) {
			return null;
		}

		if (String(element.tagName).toLowerCase() === 'select') {
			return randomizeSelect(element, random);
		}

		if (String(element.tagName).toLowerCase() === 'input') {
			return randomizeInput(element, random);
		}

		return null;
	}

	function randomizeSelect(select, random) {
		var selectElement = asElement(select);
		var selectableOptions = [];
		var selectedOption;

		if (!selectElement) {
			return null;
		}

		Array.prototype.forEach.call(selectElement.options || [], function (optionElement) {
			var option = {
				disabled: optionElement.disabled,
				text: optionElement.textContent,
				value: optionElement.value
			};

			if (isSelectableOption(option)) {
				selectableOptions.push(option);
			}
		});

		selectedOption = pickOption(selectableOptions, random);

		if (!selectedOption) {
			return null;
		}

		selectElement.value = selectedOption.value;
		dispatchFormEvent(selectElement, 'change');

		return selectedOption.value;
	}

	function randomizeInput(input, random) {
		var element = asElement(input);
		var type;
		var value;

		if (!element) {
			return null;
		}

		type = String(element.type || '').toLowerCase();

		if (type !== 'number' && type !== 'range') {
			return null;
		}

		value = pickNumericValue({
			max: element.max,
			min: element.min,
			step: element.step,
			type: type
		}, random);

		element.value = value;
		dispatchFormEvent(element, 'input');
		dispatchFormEvent(element, 'change');

		return value;
	}

	function pickOption(options, random) {
		var randomValue;
		var index;

		if (!options || !options.length) {
			return null;
		}

		randomValue = typeof random === 'function' ? random() : Math.random();
		randomValue = Math.max(0, Math.min(0.999999999, Number(randomValue) || 0));
		index = Math.floor(randomValue * options.length);

		return options[index];
	}

	function pickNumericValue(config, random) {
		var min = parseNumber(config.min, 0);
		var max = parseNumber(config.max, min);
		var step = parseStep(config.step, config.type);
		var randomValue = typeof random === 'function' ? random() : Math.random();
		var steps;
		var index;
		var value;

		if (max < min) {
			max = min;
		}

		randomValue = Math.max(0, Math.min(0.999999999, Number(randomValue) || 0));
		steps = Math.floor((max - min) / step);
		index = Math.floor(randomValue * (steps + 1));
		value = min + (index * step);
		value = Math.min(max, value);

		return formatNumericValue(value, step);
	}

	function parseNumber(value, fallback) {
		var parsed = Number(value);

		return Number.isFinite(parsed) ? parsed : fallback;
	}

	function parseStep(value, type) {
		var parsed = Number(value);

		if (String(value).toLowerCase() === 'any' || !Number.isFinite(parsed) || parsed <= 0) {
			return type === 'range' ? 1 : 1;
		}

		return parsed;
	}

	function formatNumericValue(value, step) {
		var decimals = getDecimalPlaces(step);

		if (decimals === 0) {
			return String(Math.round(value));
		}

		return value.toFixed(decimals).replace(/0+$/, '').replace(/\.$/, '');
	}

	function getDecimalPlaces(value) {
		var text = String(value);
		var decimalIndex = text.indexOf('.');

		if (decimalIndex === -1) {
			return 0;
		}

		return text.length - decimalIndex - 1;
	}

	function isSelectableOption(option) {
		var text = String(option && option.text != null ? option.text : '').trim();

		if (!option || option.disabled || option.value === undefined || option.value === null) {
			return false;
		}

		return !/^-+$/.test(text);
	}

	function isButtonInMasterGroups(button, masterGroups) {
		var buttonElement = asElement(button);
		var buttonGroups = parseGroups(buttonElement ? buttonElement.getAttribute('data-random-group') : null);

		if (masterGroups.indexOf('*') > -1) {
			return true;
		}

		for (var i = 0; i < buttonGroups.length; i++) {
			if (masterGroups.indexOf(buttonGroups[i]) > -1) {
				return true;
			}
		}

		return false;
	}

	function parseGroups(value) {
		var groups = String(value || 'global').split(/[\s,]+/);
		var normalizedGroups = [];

		for (var i = 0; i < groups.length; i++) {
			if (groups[i]) {
				normalizedGroups.push(groups[i]);
			}
		}

		return normalizedGroups.length ? normalizedGroups : ['global'];
	}

	function translate(i18n, key) {
		return i18n && typeof i18n.t === 'function' ? i18n.t(key) : key;
	}

	function asElement(value) {
		if (!value) {
			return null;
		}

		if (value.nodeType === 1 || value.nodeType === 9) {
			return value;
		}

		return value[0] || null;
	}

	function dispatchFormEvent(element, eventName) {
		var event = new Event(eventName, { bubbles: true });

		element.dispatchEvent(event);
	}

	function findDelegatedButton(root, target, selector) {
		var button = target && target.closest ? target.closest(selector) : null;

		if (!button) {
			return null;
		}

		return root === global.document || root.contains(button) ? button : null;
	}

	function forEachElement(root, selector, callback) {
		if (!root || typeof root.querySelectorAll !== 'function') {
			return;
		}

		Array.prototype.forEach.call(root.querySelectorAll(selector), callback);
	}

	global.CodaRandomSelect = {
		formatNumericValue: formatNumericValue,
		pickNumericValue: pickNumericValue,
		initialize: initialize,
		isSelectableOption: isSelectableOption,
		pickOption: pickOption,
		randomizeAssociatedControl: randomizeAssociatedControl,
		randomizeAssociatedSelect: randomizeAssociatedSelect,
		randomizeAllAssociatedControls: randomizeAllAssociatedControls,
		randomizeControl: randomizeControl,
		randomizeInput: randomizeInput,
		randomizeSelect: randomizeSelect,
		updateLabels: updateLabels
	};
})(window);

;

/* Source: js/ui/key-navigation-controller.js */
// Navegación tonal y recomendación de formato de armadura.
(function (global) {
	'use strict';

	function navigateToLinkedKey(notes, targetId, notation, notationStyle, fillSelect) {
		var selectedOption = targetId.split('_');
		var noteValue = findNoteValue(notes, selectedOption[0]);
		var scaleSelect = getElement('escala');
		var tonicSelect = getElement('tonica');

		if (selectedOption[1].indexOf('m') > -1) {
			setValue(scaleSelect, '2');
		} else {
			setValue(scaleSelect, '0');
		}

		if (selectedOption[0].indexOf('#') > 0) {
			fillSelect(tonicSelect, notes, false, null, 'notes', notation, notationStyle);
		}

		if (selectedOption[0].indexOf('b') > 0) {
			fillSelect(tonicSelect, notes, true, null, 'notes', notation, notationStyle);
		}

		if (noteValue > -1) {
			setValue(tonicSelect, String(noteValue));
		}
	}

	function findNoteValue(notes, noteName) {
		if (notes._codaIndex && notes._codaIndex.indexByName && notes._codaIndex.indexByName[noteName] !== undefined) {
			return notes._codaIndex.indexByName[noteName];
		}

		for (var i = 0; i < notes.length; i++) {
			if (notes[i].nombre === noteName || notes[i].enarmonica === noteName) {
				return i;
			}
		}

		return -1;
	}

	function applyRecommendedNotation(options, fillSelect) {
		var scaleSelect = getElement('escala');
		var tonicSelect = getElement('tonica');
		var formatInput = getCheckedFormatInput();
		var scaleIndex = parseInt(getValue(scaleSelect), 10);
		var scaleDefinition = options.data.scales[scaleIndex];
		var tonicIndex = parseInt(getValue(tonicSelect), 10);
		var tonicDefinition = options.data.notes[tonicIndex];

		if (!tonicDefinition) {
			return;
		}

		var preferFlats = options.domain.shouldPreferFlatsForKeySignature({
			notes: options.data.notes,
			scaleDefinition: scaleDefinition,
			selectedScaleIndex: scaleIndex,
			tonicName: options.ui.noteName(tonicDefinition, getValue(formatInput) === '1')
		});

		if (preferFlats == null) {
			return;
		}

		checkFormat(preferFlats ? '1' : '0');
		fillSelect(tonicSelect, options.data.notes, preferFlats, null, 'notes', options.notation, resolveNotationStyle(options));
	}

	function resolveNotationStyle(options) {
		if (options.uiState) {
			return options.uiState.getNotationStyle();
		}

		return options.notation ? options.notation.normalizeStyle(options.initialNotation || getValue(getElement('selectorNotacion'))) : 'anglosaxon';
	}

	function getElement(id) {
		return global.document ? global.document.getElementById(id) : null;
	}

	function getCheckedFormatInput() {
		return global.document ? global.document.querySelector('#interface input[type="radio"][name="formato"]:checked') : null;
	}

	function checkFormat(value) {
		var input = global.document ? global.document.querySelector('#interface input[type="radio"][name="formato"][value="' + value + '"]') : null;

		if (input) {
			input.checked = true;
		}
	}

	function getValue(element) {
		return element ? element.value : '';
	}

	function setValue(element, value) {
		if (element) {
			element.value = value;
		}
	}

	global.CodaKeyNavigation = {
		applyRecommendedNotation: applyRecommendedNotation,
		findNoteValue: findNoteValue,
		navigateToLinkedKey: navigateToLinkedKey,
		resolveNotationStyle: resolveNotationStyle
	};
})(window);

;

/* Source: js/ui/changelog-dialog-controller.js */
// Control del diálogo de novedades.
(function (global) {
	'use strict';

	var previousFocus = null;

	function initialize(i18n) {
		var doc = global.document;
		var content = doc ? doc.getElementById('controlVersiones') : null;
		var link = doc ? doc.getElementById('enlaceNovedades') : null;
		var dialog;
		var closeButton;

		if (!content || !link) {
			return;
		}

		ensureDialogStructure(i18n);
		updateTitle(i18n);
		dialog = doc.getElementById('controlVersionesDialog');
		closeButton = doc.getElementById('controlVersionesDialogClose');

		if (dialog.getAttribute('data-coda-dialog-initialized') === 'true') {
			return;
		}
		dialog.setAttribute('data-coda-dialog-initialized', 'true');

		link.addEventListener('click', function (event) {
			event.preventDefault();
			openDialog();
		});

		dialog.addEventListener('mousedown', function (event) {
			if (event.target === dialog) {
				closeDialog();
			}
		});

		closeButton.addEventListener('click', closeDialog);
		doc.addEventListener('keydown', handleDocumentKeydown);
	}

	function ensureDialogStructure(i18n) {
		var doc = global.document;
		var content = doc.getElementById('controlVersiones');
		var dialog;
		var surface;
		var titlebar;
		var title;
		var closeButton;
		var contentShell;

		if (doc.getElementById('controlVersionesDialog')) {
			return;
		}

		dialog = createElement('div', {
			'class': 'dialogoNovedades',
			'aria-labelledby': 'controlVersionesDialogTitle',
			'aria-modal': 'true',
			'hidden': '',
			'id': 'controlVersionesDialog',
			'role': 'dialog'
		});
		surface = createElement('div', { 'class': 'dialogoNovedades__surface' });
		titlebar = createElement('div', { 'class': 'dialogoNovedades__titlebar' });
		title = createElement('h2', { 'class': 'dialogoNovedades__title', 'id': 'controlVersionesDialogTitle' });
		closeButton = createElement('button', { 'class': 'dialogoNovedades__close', 'id': 'controlVersionesDialogClose', 'type': 'button' });
		closeButton.innerHTML = '<span class="material-icons" aria-hidden="true">close</span>';
		contentShell = createElement('div', { 'class': 'dialogoNovedades__content' });

		content.parentNode.insertBefore(dialog, content);
		contentShell.appendChild(content);
		titlebar.appendChild(title);
		titlebar.appendChild(closeButton);
		surface.appendChild(titlebar);
		surface.appendChild(contentShell);
		dialog.appendChild(surface);
		updateTitle(i18n);
	}

	function openDialog() {
		var doc = global.document;
		var dialog = doc.getElementById('controlVersionesDialog');
		var closeButton = doc.getElementById('controlVersionesDialogClose');

		previousFocus = doc.activeElement;
		dialog.removeAttribute('hidden');
		dialog.classList.add('isOpen');
		doc.body.classList.add('hasOpenDialog');
		closeButton.focus();
	}

	function closeDialog() {
		var doc = global.document;
		var dialog = doc.getElementById('controlVersionesDialog');

		dialog.setAttribute('hidden', 'hidden');
		dialog.classList.remove('isOpen');
		doc.body.classList.remove('hasOpenDialog');

		if (previousFocus && typeof previousFocus.focus === 'function') {
			previousFocus.focus();
		}
		previousFocus = null;
	}

	function isOpen() {
		var doc = global.document;
		var dialog = doc ? doc.getElementById('controlVersionesDialog') : null;

		return Boolean(dialog && dialog.classList.contains('isOpen'));
	}

	function updateTitle(i18n) {
		var doc = global.document;
		var titleElement = doc ? doc.getElementById('controlVersionesDialogTitle') : null;
		var closeButton = doc ? doc.getElementById('controlVersionesDialogClose') : null;
		var title = i18n ? i18n.t('changelog.dialogTitle') : 'Novedades y mejoras';
		var closeLabel = i18n ? i18n.t('changelog.close') : 'Cerrar novedades';

		if (titleElement) {
			titleElement.textContent = title;
		}

		if (closeButton) {
			closeButton.setAttribute('aria-label', closeLabel);
			closeButton.setAttribute('title', closeLabel);
		}
	}

	function handleDocumentKeydown(event) {
		if (event.key === 'Escape' && isOpen()) {
			closeDialog();
		}
	}

	function createElement(tagName, attributes) {
		var element = global.document.createElement(tagName);

		Object.keys(attributes).forEach(function (attribute) {
			element.setAttribute(attribute, attributes[attribute]);
		});

		return element;
	}

	global.CodaChangelogDialog = {
		initialize: initialize,
		updateTitle: updateTitle
	};
})(window);

